def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    urgent_opp_count = 0
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
                urgent_opp_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    players = 1 + len(alive_opponents)
    capacity = supply / float(WATER_REQ)
    scarcity = capacity < players

    if budget <= 0:
        return 0

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return min(budget, DAILY_SALARY * 0.75)
        return min(budget, DAILY_SALARY * 0.25)

    highest_prev = max(prev_bids) if prev_bids else 0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0

    danger = 0
    if hp <= 2:
        danger += 2
    elif hp <= 4:
        danger += 1
    if no_water_days >= 1:
        danger += 2
    if scarcity:
        danger += 1
    if urgent_opp_count > 0:
        danger += 1

    if danger >= 4:
        target = max(DAILY_SALARY * 0.9, highest_prev + 2)
    elif danger >= 2:
        target = max(DAILY_SALARY * 0.62, avg_prev + 1.5, highest_prev * 0.92)
    else:
        if scarcity:
            target = max(DAILY_SALARY * 0.48, avg_prev + 1)
        else:
            target = DAILY_SALARY * 0.32

    if highest_prev >= DAILY_SALARY * 0.9 and hp > 3 and no_water_days == 0:
        target = min(target, DAILY_SALARY * 0.4)

    reserve_floor = 0
    if hp <= 3 or no_water_days >= 1:
        reserve_floor = DAILY_SALARY * 0.85

    bid = max(target, reserve_floor)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    my_current_hp = my_status['hp']
    my_current_budget = my_status['budget']
    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    bid = DAILY_SALARY * 0.5

    # --- Adjust bid based on my HP ---
    if my_current_hp <= 1:
        bid = DAILY_SALARY * 0.95
    elif my_current_hp <= 3:
        bid = DAILY_SALARY * 0.75
    elif my_current_hp >= 8:
        bid = DAILY_SALARY * 0.4

    # --- Adjust bid based on supply vs demand ---
    total_water_demand_potential = WATER_REQ
    for opp in alive_opponents:
        total_water_demand_potential += opp['water_requirement']

    if current_supply >= total_water_demand_potential * 1.5:
        bid = min(bid, DAILY_SALARY * 0.3)
    elif current_supply < WATER_REQ + (num_alive_opponents * 5):
        bid = max(bid, DAILY_SALARY * 0.8)
    elif current_supply < WATER_REQ + (num_alive_opponents * 10):
        bid = max(bid, DAILY_SALARY * 0.6)

    # --- Adjust bid based on opponent's previous bids (if available) ---
    highest_prev_opp_bid = 0
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            highest_prev_opp_bid = max(highest_prev_opp_bid, prev_trace['bid'])

    if highest_prev_opp_bid > 0:
        if highest_prev_opp_bid >= DAILY_SALARY * 0.7:
            bid = max(bid, highest_prev_opp_bid + (DAILY_SALARY * 0.1))
        elif highest_prev_opp_bid >= DAILY_SALARY * 0.4:
            bid = max(bid, highest_prev_opp_bid + 1)

    # --- Adjust bid based on day progression ---
    if current_day >= EPISODE_DAYS * 0.7 and my_current_hp <= 5:
        bid = max(bid, DAILY_SALARY * 0.9)
    elif current_day >= EPISODE_DAYS * 0.8 and my_current_hp <= 8:
        bid = max(bid, DAILY_SALARY * 0.8)
    elif current_day >= EPISODE_DAYS * 0.9:
        bid = max(bid, DAILY_SALARY * 0.99)

    # Final check: ensure bid is within budget and non-negative
    bid = min(bid, my_current_budget)
    bid = max(0.0, bid)

    return bid

def get_bid(day_context, my_status, opponents_status):
    water_req = 8
    salary = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    if day == 1:
        if hp <= 3:
            bid = min(budget, salary * 0.8)
        else:
            bid = min(budget, salary * 0.5)
    else:
        alive_opponents = [o for o in opponents_status.values() if o['alive']]
        prev_bids = []
        for opp in alive_opponents:
            prev = opp.get('previous_trace')
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev['bid'])
        if prev_bids:
            max_prev = max(prev_bids)
            if max_prev > salary * 0.8:
                if hp > 4:
                    bid = min(budget, salary * 0.4)
                else:
                    bid = min(budget, max(salary * 0.6, max_prev + 1))
            else:
                bid = min(budget, salary * 0.5)
        else:
            if hp <= 3:
                bid = min(budget, salary * 0.8)
            else:
                bid = min(budget, salary * 0.5)
    return min(bid, budget)
